//! Sound: plays `assets/sfx/manifest.ron` (generated by tools/sfxgen).
//!
//! * One-shots: send [`PlaySfx`] (random file + random pitch from the manifest entry).
//! * Loops (in game): wind (speed), boost (while boosting), reel (while reeling a tether),
//!   slide (while sliding) — volume/pitch driven every frame from the local player's state.
//! * Movement events (jump, land, tether fire/attach/release, boost burst, wall hit, footsteps)
//!   are voiced here from `FrameMoveEvents`.
//! * Every file is loaded during the loading screen (no asset loads mid-match).

use crate::assets_dir;
use crate::player::{FrameMoveEvents, LocalPlayer, PlayerSim};
use crate::settings::Settings;
use crate::state::AppState;
use crate::tick::FrameSet;
use crate::util::{v3, Rng};
use crate::warmup::LoadingBlockers;
use bd_core::input::buttons;
use bevy::audio::{AudioSink, AudioSinkPlayback, AudioSource, PlaybackSettings, Volume};
use bevy::platform::collections::HashMap;
use bevy::prelude::*;
use serde::Deserialize;
use std::borrow::Cow;

#[derive(Deserialize, Debug, Clone)]
struct ManifestEntry {
    files: Vec<String>,
    #[serde(default)]
    #[allow(dead_code)]
    category: String,
    #[serde(default = "one")]
    volume: f32,
    #[serde(default)]
    looping: bool,
    #[serde(default = "unit_pitch")]
    pitch: (f32, f32),
}

fn one() -> f32 {
    1.0
}
fn unit_pitch() -> (f32, f32) {
    (1.0, 1.0)
}

#[derive(Deserialize, Debug)]
struct Manifest {
    #[allow(dead_code)]
    sample_rate: u32,
    sounds: std::collections::HashMap<String, ManifestEntry>,
}

struct Sound {
    handles: Vec<Handle<AudioSource>>,
    volume: f32,
    pitch: (f32, f32),
    #[allow(dead_code)]
    looping: bool,
}

#[derive(Resource, Default)]
pub struct SfxBank {
    sounds: HashMap<String, Sound>,
    all: Vec<Handle<AudioSource>>,
    ready: bool,
}

impl SfxBank {
    pub fn has(&self, name: &str) -> bool {
        self.sounds.contains_key(name)
    }
}

/// Play a one-shot. `gain` multiplies the manifest volume, `pitch` the random manifest pitch.
#[derive(Message, Clone, Debug)]
pub struct PlaySfx {
    pub name: Cow<'static, str>,
    pub gain: f32,
    pub pitch: f32,
}

impl PlaySfx {
    pub fn new(name: impl Into<Cow<'static, str>>) -> Self {
        Self { name: name.into(), gain: 1.0, pitch: 1.0 }
    }
    pub fn gain(mut self, g: f32) -> Self {
        self.gain = g;
        self
    }
    pub fn pitch(mut self, p: f32) -> Self {
        self.pitch = p;
        self
    }
}

#[derive(Component, Clone, Copy, PartialEq, Eq, Debug)]
enum LoopKind {
    Wind,
    Boost,
    Reel,
    Slide,
}

#[derive(Component)]
struct SfxLoop {
    kind: LoopKind,
    base: f32,
    current: f32,
}

#[derive(Resource)]
struct AudioRng(Rng);

pub struct AudioFxPlugin;

impl Plugin for AudioFxPlugin {
    fn build(&self, app: &mut App) {
        app.init_resource::<SfxBank>()
            .insert_resource(AudioRng(Rng::new(0xa0d10)))
            .add_message::<PlaySfx>()
            .add_systems(Startup, load_bank)
            .add_systems(Update, track_loaded.run_if(in_state(AppState::Loading)))
            .add_systems(OnEnter(AppState::InGame), spawn_loops)
            .add_systems(OnExit(AppState::InGame), despawn_loops)
            .add_systems(Update, (movement_sounds, update_loops).after(FrameSet::Sim).before(FrameSet::Present))
            .add_systems(Update, play_sfx.after(FrameSet::Present));
    }
}

fn load_bank(asset_server: Res<AssetServer>, mut bank: ResMut<SfxBank>, mut blockers: ResMut<LoadingBlockers>) {
    let path = assets_dir().join("sfx").join("manifest.ron");
    let manifest = match std::fs::read_to_string(&path).map_err(|e| e.to_string()).and_then(|t| ron::from_str::<Manifest>(&t).map_err(|e| e.to_string())) {
        Ok(m) => m,
        Err(e) => {
            warn!("sfx: no manifest at {} ({e}); running silent", path.display());
            return;
        }
    };
    for (name, e) in manifest.sounds {
        let handles: Vec<Handle<AudioSource>> = e.files.iter().map(|f| asset_server.load::<AudioSource>(f.clone())).collect();
        bank.all.extend(handles.iter().cloned());
        bank.sounds.insert(name, Sound { handles, volume: e.volume, pitch: e.pitch, looping: e.looping });
    }
    info!("sfx: {} sounds, {} files queued", bank.sounds.len(), bank.all.len());
    blockers.audio_pending = true;
}

fn track_loaded(asset_server: Res<AssetServer>, mut bank: ResMut<SfxBank>, mut blockers: ResMut<LoadingBlockers>) {
    if bank.ready || !blockers.audio_pending {
        return;
    }
    let pending = bank
        .all
        .iter()
        .filter(|h| {
            !asset_server.is_loaded_with_dependencies(h.id())
                && !matches!(asset_server.get_load_state(h.id()), Some(bevy::asset::LoadState::Failed(_)))
        })
        .count();
    if pending == 0 {
        bank.ready = true;
        blockers.audio_pending = false;
        info!("sfx: all files loaded");
    }
}

fn play_sfx(
    mut commands: Commands,
    bank: Res<SfxBank>,
    settings: Res<Settings>,
    mut rng: ResMut<AudioRng>,
    mut events: MessageReader<PlaySfx>,
) {
    for e in events.read() {
        let Some(s) = bank.sounds.get(e.name.as_ref()) else { continue };
        if s.handles.is_empty() || settings.master_volume <= 0.0 {
            continue;
        }
        let r = &mut rng.0;
        let h = s.handles[(r.next_u32() as usize) % s.handles.len()].clone();
        let speed = r.range(s.pitch.0, s.pitch.1) * e.pitch;
        commands.spawn((
            AudioPlayer::new(h),
            PlaybackSettings::DESPAWN.with_volume(Volume::Linear(s.volume * e.gain)).with_speed(speed.max(0.05)),
        ));
    }
}

fn spawn_loops(mut commands: Commands, bank: Res<SfxBank>) {
    for (kind, name) in [
        (LoopKind::Wind, "wind_loop"),
        (LoopKind::Boost, "boost_loop"),
        (LoopKind::Reel, "tether_reel_loop"),
        (LoopKind::Slide, "slide_loop"),
    ] {
        let Some(s) = bank.sounds.get(name) else { continue };
        let Some(h) = s.handles.first() else { continue };
        commands.spawn((
            SfxLoop { kind, base: s.volume, current: 0.0 },
            AudioPlayer::new(h.clone()),
            PlaybackSettings::LOOP.with_volume(Volume::Linear(0.0)),
        ));
    }
}

fn despawn_loops(mut commands: Commands, q: Query<Entity, With<SfxLoop>>) {
    for e in &q {
        commands.entity(e).despawn();
    }
}

fn update_loops(
    time: Res<Time<Real>>,
    settings: Res<Settings>,
    player: Query<&PlayerSim, With<LocalPlayer>>,
    inputs: Res<crate::input::LocalInputState>,
    mut loops: Query<(&mut SfxLoop, &mut AudioSink)>,
) {
    let Ok(sim) = player.single() else { return };
    let s = &sim.state;
    let speed = v3(s.vel).length();
    let reeling = s.tethered() && (inputs.current.held(buttons::REEL) || inputs.current.reel_notches != 0);
    let dt = time.delta_secs();
    for (mut l, mut sink) in &mut loops {
        let (target, pitch) = match l.kind {
            LoopKind::Wind => {
                let k = ((speed - 6.0) / 30.0).clamp(0.0, 1.0);
                (k * k * 1.2, 0.8 + k * 0.6)
            }
            LoopKind::Boost => (if s.boosting { 1.0 } else { 0.0 }, 1.0),
            LoopKind::Reel => (if reeling { 1.0 } else { 0.0 }, 1.0),
            LoopKind::Slide => (if s.sliding { (speed / 14.0).clamp(0.3, 1.0) } else { 0.0 }, 0.9 + (speed / 40.0).min(0.3)),
        };
        // Fast attack, slower release (no clicks).
        let rate = if target > l.current { 25.0 } else { 8.0 };
        l.current += (target - l.current) * (1.0 - (-rate * dt).exp());
        sink.set_volume(Volume::Linear(l.current * l.base * settings.master_volume));
        sink.set_speed(pitch);
    }
}

fn movement_sounds(
    events: Res<FrameMoveEvents>,
    player: Query<&PlayerSim, With<LocalPlayer>>,
    mut out: MessageWriter<PlaySfx>,
    mut stride: Local<f32>,
) {
    for ev in &events.0 {
        if ev.jumped {
            out.write(PlaySfx::new("jump").gain(if ev.perfect_hop { 1.0 } else { 0.8 }).pitch(if ev.perfect_hop { 1.06 } else { 1.0 }));
        }
        if let Some(l) = ev.landed {
            if l.impact_speed > 14.0 {
                out.write(PlaySfx::new("land_heavy").gain((l.impact_speed / 25.0).clamp(0.6, 1.2)));
            } else if l.impact_speed > 3.0 {
                out.write(PlaySfx::new("land_light").gain((l.impact_speed / 12.0).clamp(0.4, 1.0)));
            }
        }
        for i in 0..2 {
            if ev.tether_fired[i] {
                out.write(PlaySfx::new("tether_fire"));
            }
            if ev.tether_attached[i] {
                out.write(PlaySfx::new("tether_attach"));
            }
            if ev.tether_released[i] || ev.tether_broken[i] {
                out.write(PlaySfx::new("tether_release"));
            }
        }
        if ev.boost_burst {
            out.write(PlaySfx::new("boost_burst"));
        }
        if let Some(w) = ev.wall_hit
            && w.speed > 8.0
        {
            out.write(PlaySfx::new("land_heavy").gain((w.speed / 25.0).clamp(0.5, 1.0)).pitch(1.1));
        }
    }
    // Footsteps from distance walked on the ground.
    if let Ok(sim) = player.single() {
        let s = &sim.state;
        if s.grounded && !s.sliding {
            let d = v3(s.pos - sim.prev.pos);
            let h = Vec2::new(d.x, d.z).length() * events.0.len().max(1) as f32;
            *stride += h;
            if *stride > 2.6 {
                *stride = 0.0;
                out.write(PlaySfx::new("footstep"));
            }
        } else {
            *stride = 1.8; // first step comes quickly after landing
        }
    }
}
